   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="漫天细碎锋利的暗蚀刃片撕裂气流，如同暴雨般笼罩整片上层洞窟，每一枚刃片都裹挟浓郁的虚粒子，落地便能腐蚀坚硬岩层，地面早已布满密密麻麻的腐蚀坑洼。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
