   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="失去特拉西的控制，巨型源晶花变得愈发狂躁无序。粗壮的根茎毫无规律地疯狂抽打岩壁与地面，破碎的碎石、腐蚀汁液四处飞溅。甚至有些根茎抽打在身下的培养皿上，将培养皿抽的稀碎。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
