   [154]={next_id=155, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="碎裂声轰然炸开，密密麻麻的裂纹瞬间遍布整块晶核表层。原本稳固的彩色结晶再也无法承载狂暴的能量，寸寸崩裂、瓦解、坠落。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [155]={next_id=156, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="晶核破碎的刹那，刺眼的白光瞬间吞噬你的所有感官，周遭的溶洞、结晶、黑暗尽数消失。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_405.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
